```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times the notification is offered before the node gives up.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input this call received in the shared store.
        state_rw::put("last-input", &feed_url);

        // Clock: the time this heartbeat was taken.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure is a value
        // and counts as zero characters; a URL outside the allowlist traps at
        // the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: the message carries only the node's own measurements,
        // never the fetched text.
        let mut message = String::from("heartbeat: seconds=");
        message.push_str(&seconds.to_string());
        message.push_str(" fetched=");
        message.push_str(&fetched.to_string());

        let mut notified = false;
        let mut attempt = 0;
        while !notified && attempt < NOTIFY_ATTEMPTS {
            notified = notifier::notify(&message);
            attempt += 1;
        }

        // The contract is `ensures notified == true`. If the channel refused
        // the notification, no honest output satisfies it, so the node traps
        // rather than report an acceptance that did not happen.
        if !notified {
            panic!("heartbeat notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

The world imports `aap:caps/state-rw@0.1.0` as requested, so the component will only instantiate on a host that already provides that interface to this node. If the graph definition has not yet been updated when this is deployed, instantiation fails rather than the write being skipped.

